def raypoint(m,uv,z):
 c=m['cameras']['robot_r1:zed_link:Camera:0'];K=np.array(c['intrinsic_cv']);E=np.array(c['extrinsic_cv']);R=E[:,:3];T=np.eye(4);T[:3,:3]=R;T[:3,3]=E[:,3];o=np.linalg.inv(T)[:3,3];d=np.linalg.inv(R)@np.array([(uv[0]-112)/K[0,0],(uv[1]-112)/K[1,1],1]);return o+(z-o[2])/d[2]*d
P=raypoint(m53,(190,190),1.05);print('P',P)
